//! G14 activity-collection parity: the Rust aggregation (collect::worker_from_scan) shaped by the
//! report builder reproduces the TS scanner-answer reports
//! (`tests/spec/analytics-writers/collect-vectors.json`, regenerated by
//! `generate-collect-vectors.mjs`). The pricing facts are the TS-resolved ones the generator
//! captured, so this pins the aggregation arithmetic, not the models.dev registry.
use aac_store::collect::{self, Pricing, PricingResolution, Rates};
use aac_store::report::{self, ReportArgs};
use serde_json::{Map, Value, json};
use std::collections::{HashMap, HashSet};

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/spec/analytics-writers/collect-vectors.json"
    );
    let text = std::fs::read_to_string(path).expect("collect-vectors.json (run the generator)");
    serde_json::from_str(&text).expect("vectors parse")
}

/// Numbers compare by value; cost floats round to the nano the store persists (`contract::nano`),
/// so sub-nano IEEE ordering noise in the pricing arithmetic is not a consumer-visible difference.
fn numbers(value: &Value) -> Value {
    match value {
        Value::Number(n) => {
            let f = n.as_f64().expect("finite vector number");
            json!((f * 1e9).round() / 1e9)
        }
        Value::Array(list) => Value::Array(list.iter().map(numbers).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), numbers(v)))
                .collect::<Map<String, Value>>(),
        ),
        other => other.clone(),
    }
}

struct FixturePricing {
    facts: HashMap<String, PricingResolution>,
}

impl Pricing for FixturePricing {
    fn resolve(&self, model: &str, provider: Option<&str>) -> PricingResolution {
        let key = format!("{model}\u{0}{}", provider.unwrap_or(""));
        self.facts.get(&key).cloned().unwrap_or(PricingResolution {
            rates: Rates {
                input: 0.0,
                output: 0.0,
                cache_creation: 0.0,
                cache_read: 0.0,
            },
            source: "fallback".into(),
        })
    }
}

fn pricing(doc: &Value) -> FixturePricing {
    let mut facts = HashMap::new();
    for (key, value) in doc["facts"].as_object().expect("facts") {
        let rates = &value["rates"];
        facts.insert(
            key.clone(),
            PricingResolution {
                rates: Rates {
                    input: rates["input"].as_f64().unwrap_or(0.0),
                    output: rates["output"].as_f64().unwrap_or(0.0),
                    cache_creation: rates["cacheCreation"].as_f64().unwrap_or(0.0),
                    cache_read: rates["cacheRead"].as_f64().unwrap_or(0.0),
                },
                source: value["source"].as_str().unwrap_or("fallback").to_string(),
            },
        );
    }
    FixturePricing { facts }
}

#[test]
fn collection_matches_the_ts_aggregation() {
    let doc = vectors();
    let now = doc["now"].as_i64().expect("now");
    let window_from = doc["windowFromMs"].as_i64().expect("windowFromMs");
    let pricing = pricing(&doc);
    let local: HashMap<String, Vec<Value>> = HashMap::new();
    let local_complete: HashSet<String> = HashSet::new();
    let scanner_owned: HashSet<String> = HashSet::new();
    for case in doc["cases"].as_array().expect("cases") {
        let kind = case["kind"].as_str().expect("kind");
        let host = case["host"].as_str().expect("host");
        let rows = case["rows"].as_array().expect("rows").clone();
        let srows = case["srows"].as_array().expect("srows").clone();
        let worker = collect::worker_from_scan(&rows, &srows, kind, host, now, &pricing);
        let remote = vec![json!({ "tool": kind, "host": host, "data": worker })];
        let states = vec![json!({
            "tool": kind,
            "host": host,
            "state": "ok",
            "lastScanAt": aac_num::ecma::to_iso_string(now).expect("iso now"),
        })];
        let args = ReportArgs {
            local: &local,
            remote: &remote,
            states: &states,
            window_from_ms: window_from,
            now,
            local_complete: &local_complete,
            scanner_owned: &scanner_owned,
        };
        let got = numbers(&Value::Array(report::build_activity_reports(&args)));
        let expected = numbers(&case["expected"]);
        assert_eq!(got, expected, "case {}", case["name"].as_str().unwrap_or("?"));
    }
}

#[test]
fn provider_normalization_matches_the_alias_map() {
    assert_eq!(
        collect::normalize_provider(Some("claude")).as_deref(),
        Some("anthropic")
    );
    assert_eq!(collect::normalize_provider(Some("CODEX")).as_deref(), Some("openai"));
    assert_eq!(
        collect::normalize_provider(Some("  Gemini ")).as_deref(),
        Some("google")
    );
    assert_eq!(collect::normalize_provider(Some("qwen")).as_deref(), Some("alibaba"));
    assert_eq!(
        collect::normalize_provider(Some("anthropic")).as_deref(),
        Some("anthropic")
    );
    assert_eq!(collect::normalize_provider(Some("")).as_deref(), None);
    assert_eq!(collect::normalize_provider(None).as_deref(), None);
}

#[test]
fn session_keys_match_the_published_digest() {
    // sha256("aac-session-v1:claude:raw-session") first 16 hex; the full hash is 64 hex.
    let key = collect::session_key("claude", "raw-session");
    let hash = collect::session_hash("claude", "raw-session");
    assert_eq!(key.len(), 16);
    assert_eq!(hash.len(), 64);
    assert!(hash.starts_with(&key));
    assert!(key.bytes().all(|b| b.is_ascii_hexdigit()));
}
